import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Kanuni ya Kurudisha Maarifa Tu","description":"","frontmatter":{},"headers":[],"relativePath":"sw/87-仅回传知识原则.md","filePath":"sw/87-仅回传知识原则.md","lastUpdated":null}'),e={name:"sw/87-仅回传知识原则.md"};function h(k,a,o,s,r,m){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kanuni-ya-kurudisha-maarifa-tu" tabindex="-1">Kanuni ya Kurudisha Maarifa Tu <a class="header-anchor" href="#kanuni-ya-kurudisha-maarifa-tu" aria-label="Permalink to &quot;Kanuni ya Kurudisha Maarifa Tu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>87</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kurudisha maarifa tu, usafi wa taarifa, marufuku ya kurudisha vifaa, usimbaji wa maarifa, ukaguzi wa kurudisha</td></tr></tbody></table><h2 id="_1-mazingira-ya-kisheria-na-wazo-la-msingi-wa-kanuni" tabindex="-1">1. Mazingira ya Kisheria na Wazo la Msingi wa Kanuni <a class="header-anchor" href="#_1-mazingira-ya-kisheria-na-wazo-la-msingi-wa-kanuni" aria-label="Permalink to &quot;1. Mazingira ya Kisheria na Wazo la Msingi wa Kanuni&quot;">​</a></h2><p>Kanuni ya &quot;kurudisha maarifa tu&quot; ni moja ya kanuni za msingi za kichunguzi cha kati ya ndege na kurudi nyuma kwa wakati wa ustaarabu wa symbiosis wa nanga, na chimbuko lake cha kisheria kinaweza kutafsiriwa hadi kwa Kifungu cha 48 cha &quot;Katiba ya Symbiosis&quot;: &quot;Vifaa vyovyote, nishati, na viumbe vilivyopatikana kutoka kwa ndege nyingine au vipindi vingine vya wakati, havifai kuletwa kwenye ndege ya mwenyewe bila idhini maalum; matokeo halali ya shughuli za kichunguzi vinagawiwa kwa maarifa na taarifa za kihisi tu.&quot; Uanzishwaji wa kanuni hii ni uchaguzi wa kisheria ambao Hengyuanzhou ulifanya baada ya kukusanya masomo ya maumivu ya uchunguzi wa kati ya ndege wa awali.</p><p>Katika awali ya uanzishwaji wa ustaarabu wa symbiosis wa nanga, uchunguzi wa kati ya ndege bado ulikuwa katika hali isiyo na mpangilio. Wachunguzi waochukua sampuli za vifaa, kristali za nishati, na hata viumbe kutoka kwa ndege nyingine kwenda kwenye ndege ya mwenyewe kwa ajili ya utafiti, na hili lilisababisha &quot;majukwao ya uchafuzi wa kati ya ndege&quot; makali. Kisa maarufu zaidi ni &quot;Kisa cha Kristali ya Nje&quot; — kristali ya nishati iliyotolewa kutoka kwa ndege ya udhihirisho wa nishati, kwa sababu vigezo vya sheria vya haja viwe sawa na ndege ya mwenyewe, ilisababisha mkoso wa sheria ulioendelea kwa miaka mitatu katika mtandao wa sheria wa ndege ya mwenyewe, na kusababisha utotovu katika mfumo wa uboreshaji wa tatu maeneo ya nyota, na watu elfu wengi wa uboreshaji waliudhuliwa kwa kiwango tofauti. Uchunguzi wa baadaye ulionyesha kuwa, kwamba kanuni ya &quot;kurudisha maarifa tu&quot; ingefuatwa wakati huo, janga hili lingeweza kuepukwa kabisa.</p><p>Wazo la msingi wa kanuni ya &quot;kurudisha maarifa tu&quot; ni: maarifa ni njia pekee ya salama katika mwingiliano kati ya ustaarabu. Vifaa na nishati hubeba taarifa za sheria za ndege ya chanzo chao, na baada ya kuingia katika mazingira ya sheria tofauti zinaweza kusababisha athari zisizotarajiwa; wakati maarifa kama taarifa ya kihisi, baada ya usimbaji na usafi unaofaa, yanaweza kutenga alama za sheria za ndege ya chanzo chao, na kuwa rasilimali salama inayoweza kushirikishwa kati ya ndege.</p><h2 id="_2-ufafanuzi-na-uainishaji-wa-maarifa" tabindex="-1">2. Ufafanuzi na Uainishaji wa &quot;Maarifa&quot; <a class="header-anchor" href="#_2-ufafanuzi-na-uainishaji-wa-maarifa" aria-label="Permalink to &quot;2. Ufafanuzi na Uainishaji wa &quot;Maarifa&quot;&quot;">​</a></h2><p>Chini ya mfumo wa kisheria wa kanuni ya &quot;kurudisha maarifa tu&quot;, &quot;maarifa&quot; yana ufafanuzi na uainishaji mkali. Sio taarifa zote zinazoweza kuchukuliwa kama &quot;maarifa&quot; na kurudishwa kwa uhuru — taarifa ya kihisi tu ambayo imepitia mchakato wa &quot;usafi wa taarifa&quot; na imethibitishwa kuwa haibebi uchafuzi wowote wa sheria ndiyo inayofuata viwango vya kurudisha.</p><p>Maarifa inagawanywa katika aina tatu kulingana na kiwango cha ukihisi na kiwango cha usalama:</p><table tabindex="0"><thead><tr><th>Aina ya Maarifa</th><th>Ufafanuzi</th><th>Kiwango cha Usalama</th><th>Hitaji la Kurudisha</th></tr></thead><tbody><tr><td>Maarifa ya daraja la kwanza (maarifa ya kihisi safi)</td><td>Dhana za kihisi zilizotengwa kabisa na mchanga wa vifaa, nadharia za hisabati, tokea za kimantiki, mawazo ya falsafa, n.k.</td><td>Juu zaidi (kijani)</td><td>Inaweza kurudishwa moja kwa moja, haihitaji idhini maalum</td></tr><tr><td>Maarifa ya daraja la pili (maarifa ya maelezo)</td><td>Taarifa za maelezo kuhusu vitu vya dhahiri, ikiwa ni pamoja na rekodi za kihistoria, data za jiografia, sifa za kibaolojia, maelezo ya kitamaduni, n.k.</td><td>Kati (njano)</td><td>Lazima ipitie mchakato wa usafi wa taarifa, irudishwe baada ya uidhinishwe na Ofisi ya Usimamizi wa Ndege</td></tr><tr><td>Maarifa ya daraja la tatu (maarifa ya kiufundi)</td><td>Maarifa ya vitendo vinavyojumuisha vigezo vya kiufundi mahususi, mipango ya uhandisi, mbinu za uboreshaji</td><td>Chini zaidi (machungwa)</td><td>Lazima ipitie usafi mkali wa taarifa na tathmini ya usalama, irudishwe baada ya uidhinishwe maalum na Baraza la Nanga</td></tr></tbody></table><p>Maudhui yafuatayo hayajangi katika kategoria ya &quot;maarifa&quot;, na kurudishwa kwake kunakatazwa kwa mkali: sampuli za vifaa katika aina yoyote (ikiwa ni pamoja na vijidudu, seli, vipande vya jeni), kristali za nishati au vifaa vya kuhifadhi nishati katika aina yoyote, viumbe wowote au miili ya fahari yenye fahari ya kujitegemea, data asili yoyote isiyopitia usafi wa taarifa, na maelezo yoyote ya kiufundi yanayoweza kutumika kwa uboreshaji wa mauaji.</p><h2 id="_3-teknolojia-ya-usafi-wa-taarifa" tabindex="-1">3. Teknolojia ya Usafi wa Taarifa <a class="header-anchor" href="#_3-teknolojia-ya-usafi-wa-taarifa" aria-label="Permalink to &quot;3. Teknolojia ya Usafi wa Taarifa&quot;">​</a></h2><p>Usafi wa taarifa ni kipengele cha msingi cha kiufundi cha kuhakikisha usalama wa maarifa yanayorudishwa. Lengo lake la msingi ni kutenga kabisa alama za sheria za ndege ya chanzo zilizobebwa katika taarifa asili, na kubaki na maudhui ya maana safi tu. Mchakato wa usafi wa taarifa umegawanywa katika hatua nne:</p><h3 id="_3-1-kuangamua-taarifa" tabindex="-1">3.1 Kuangamua Taarifa <a class="header-anchor" href="#_3-1-kuangamua-taarifa" aria-label="Permalink to &quot;3.1 Kuangamua Taarifa&quot;">​</a></h3><p>Kwanza, taarifa asili inayotakiwa kurudishwa inagongwa kwa kimuundo, na inagawanywa katika sehemu mbili: &quot;maudhui ya maana&quot; na &quot;alama za mchanga&quot;. Maudhui ya maana ni maana ya kihisi ambayo taarifa inataka kuelezea, na alama za mchanga ni vigezo vya sheria za ndege ya chanzo ambayo taarifa inayochuma wakati wa uhifadhi na usafirishaji. Kuangamua taarifa kunatekelezwa kupitia &quot;algoritmu ya kutenga maana-mchanga&quot;, algoritmu hii inaweza kutambua na kutenga sehemu za maana na sehemu za sheria ndani ya taarifa.</p><h3 id="_3-2-kutenga-sheria" tabindex="-1">3.2 Kutenga Sheria <a class="header-anchor" href="#_3-2-kutenga-sheria" aria-label="Permalink to &quot;3.2 Kutenga Sheria&quot;">​</a></h3><p>Inafanyika kutenga sheria kamili kwa alama za mchanga zilizotengwa. Njia ya kutenga ni kupitisha taarifa kupitia &quot;njia ya kutuliza sheria&quot; — hii ni njia maalum ya usafirishaji ambayo vigezo vya sheria vimewekwa kuwa sawa kabisa, na wakati taarifa inapopita, vigezo vyote vya sheria visivyo sawa ambavyo vimebeba vinaingizwa na ukuta wa njia. Baada ya kutenga sheria, taarifa haitabeba tena alama wowote ya sheria ya ndege ya chanzo.</p><h3 id="_3-3-kujenga-tena-maana" tabindex="-1">3.3 Kujenga Tena Maana <a class="header-anchor" href="#_3-3-kujenga-tena-maana" aria-label="Permalink to &quot;3.3 Kujenga Tena Maana&quot;">​</a></h3><p>Kwa msingi wa kutenga sheria, inafanyika usimbaji wa tena wa maudhui ya maana, na kutumia mfumo wa kawaida wa usimbaji wa taarifa wa ndege ya mwenyewe kujenga tena taarifa. Kujenga tena maana kunahakikisha kuwa maarifa yanayorudishwa yanaweza kusomwa na kueleweka kwa usahihi katika mazingira ya sheria ya ndege ya mwenyewe, wakati huo huo pia inaondoa zaidi muundo wowote wa taarifa wa ndege ya chanzo ambao unaweza kubaki.</p><h3 id="_3-4-kugundua-usalama" tabindex="-1">3.4 Kugundua Usalama <a class="header-anchor" href="#_3-4-kugundua-usalama" aria-label="Permalink to &quot;3.4 Kugundua Usalama&quot;">​</a></h3><p>Taarifa baada ya usafi lazima ipitie uchunguzi mkali wa usalama, ikiwa ni pamoja na: uchunguzi wa mabaki ya sheria (kuthibitisha kuwa taarifa haibebi vigezo vyovyote vya sheria vya nje), uchunguzi wa ukamilifu wa maana (kuthibitisha kuwa mchakato wa usafi haujabadilisha maudhui ya maana ya taarifa), na tathmini ya hatari inayoweza kutokea (kutathmini athari za kijamii na za usalama ambazo ukuzaji wa maarifa haya katika ndege ya mwenyewe kunaweza kuleta). Taarifa tu ambayo imepitia uchunguzi zote tatu ndiyo inaruhusiwa kurudishwa.</p><h2 id="_4-mchakato-wa-kurudisha-na-mfumo-wa-ukaguzi" tabindex="-1">4. Mchakato wa Kurudisha na Mfumo wa Ukaguzi <a class="header-anchor" href="#_4-mchakato-wa-kurudisha-na-mfumo-wa-ukaguzi" aria-label="Permalink to &quot;4. Mchakato wa Kurudisha na Mfumo wa Ukaguzi&quot;">​</a></h2><p>Kurudisha maarifa kunafuata usimamizi mkali wa mchakato. Operesheni kamili ya kurudisha inajumuisha viungo vifuatavyo:</p><ol><li><strong>Kupanga Maarifa</strong>: Timu ya kichunguzi inapanga matokeo ya utafiti katika hati za maarifa zilizozingatiwa, na kuashiria wazi aina ya maarifa na muhtasari wa maudhui.</li><li><strong>Ombi la Usafi</strong>: Kuwasilisha ombi la usafi wa maarifa na kurudisha kwa Ofisi ya Usimamizi wa Ndege au Kamati ya Sheria za Wakati, na kuambatisha hati ya maarifa na faili ya idhini ya kazi ya kichunguzi.</li><li><strong>Usafi wa Taarifa</strong>: Timu ya kiufundi ya usafi wa taarifa ya wataalamu inafanya mchakato wa usafi wa taarifa wa hatua nne kwa hati ya maarifa.</li><li><strong>Kugundua Usalama</strong>: Maarifa baada ya usafi inapitia uchunguzi wa tatu unaofanywa na shirika la kujitegemea la uchunguzi wa usalama.</li><li><strong>Uidhinishaji na Kurudisha</strong>: Baada ya kupita uchunguzi, shirika la uidhinishaji linasaini idhini ya kurudisha, na maarifa yanarudishwa kwa hifadhi ya data ya maarifa ya ndege ya mwenyewe kupitia njia ya usimbaji ya mtandao wa nanga.</li><li><strong>Kuhifadhi katika Hifadhi</strong>: Maarifa yaliyorudishwa baada ya kuthibitishwa na hifadhi ya maarifa ya ndege ya mwenyewe huingizwa rasmi katika hifadhi, na kufunguliwa kwa watafiti wenye idhini inayolingana.</li></ol><p>Operesheni zote za kurudisha lazima zipitie &quot;ukaguzi wa kurudisha&quot;. Maudhui ya ukaguzi yanajumuisha: chanzo cha maarifa yanayorudishwa ni halali au la, mchakato wa usafi unafuata kanuni au la, uchunguzi wa usalama umekamilika au la, na utaratibu wa uidhinishaji unafuata kanuni au la. Ukaguzi unawajibika na Ofisi ya Ukaguzi wa Kurudisha Maarifa chini ya Kamati ya Ufuatiliaji wa Nanga, inayofanya uchunguzi wa sampuli kwa operesheni zote za kurudisha za robo hiyo kila robo, na kufanya ukaguzi kamili mara moja kila mwaka. Matokeo ya ukaguzi yanaripotiwa kwa Baraza la Nanga, na muhtasari unafichuliwa kwa umma.</p><h2 id="_5-vitendo-vya-ukiukaji-na-wajibu-wa-kisheria" tabindex="-1">5. Vitendo vya Ukiukaji na Wajibu wa Kisheria <a class="header-anchor" href="#_5-vitendo-vya-ukiukaji-na-wajibu-wa-kisheria" aria-label="Permalink to &quot;5. Vitendo vya Ukiukaji na Wajibu wa Kisheria&quot;">​</a></h2><p>Vitendo vya ukiukaji wa kanuni ya &quot;kurudisha maarifa tu&quot; vinajumuisha: kurudisha taarifa isiyosafiw bila uidhinishaji, kuficha sampuli za vifaa kama maarifa ili kurudisha, kuficha kwa makudi alama za sheria za ndege ya chanzo ndani ya maarifa yanayorudishwa, na kusaidia wengine kufanya kurudisha haramu.</p><p>Kulingana na &quot;Katiba ya Symbiosis&quot; na &quot;Kanuni ya Usimamizi wa Mwingiliano wa Kati ya Ndege&quot;, wajibu wa kisheria kwa vitendo vya kurudisha vilivyoukia umoja: kunyimilia vifaa na taarifa zilizorudishwa kwa ukiukaji, kusimamisha au kuondoa kwa watu wanaohusika ufanisi wa kichunguzi na kuvuka, kulipa faini sawa na zaidi ya mara 10 ya thamani ya vifaa vilivyoukia umoja, kukabiliwa na adhabu ya gerezani katika hali nzito, na kubeba gharama zote za urekebishaji na wajibu wa fidia ikiwa kusababisha uchafuzi wa sheria au uharibifu wa mazingira.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kanuni ya &quot;kurudisha maarifa tu&quot; ni misingi ya hekima ya ustaarabu wa symbiosis wa nanga katika uwanja wa mwingiliano wa kati ya ndege. Kwa ufafanuzi mkali, teknolojia ya usafi iliyokomaa, mchakato wa kurudisha unaofuata kanuni, na wajibu wa kisheria mkali, inajenga &quot;kizuizi cha moto cha usalama wa maarifa&quot; chenye uimara. Maana ya kanuni hii sio tu kuzuia uchafuzi wa kiwango cha kimwili, bali muhimu zaidi ni kuwa imeanzisha mtazamo wa maadili wa mwingiliano wa ustaarabu — mwingiliano kati ya ustaarabu unapaswa kuwa na msingi wa mgongano wa mawazo, siyo kusudi la mauaji wa vifaa.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>84-Muhtasari wa Itifaki ya Kichunguzi</li><li>88-Kanuni za Maadili za Kati ya Ndege</li><li>66-Teknolojia ya Mawasiliano ya Kati ya Ndege</li></ul>',32)])])}const d=i(e,[["render",h]]);export{y as __pageData,d as default};
